this.schttp = this.schttp || {}
// MaxEntries 为缓存空间级别配置, 统一配置
const MaxEntriesConfig = {
  dynamicData: 100,
  addressbook: 50,
  localhost: 1000,
}
this.schttp.workboxGetRouteList = [
  {
    capture: ({ url }) => ['www.facebook.com'].some(host => url.host === host),
    strategy: 'NetworkOnly',
  },
  {
    // 首页推荐
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/recommend/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 8,
    },
    CacheRecognizePluginConfig: true,
  },
  // {
  //   // 商品详情
  //   capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/.+-p-(\d+)(-cat-(\d+))?\.html/,
  //   strategy: 'CacheFirst',
  //   strategyOptions: {
  //     cacheName: 'dynamicData',
  //   },
  //   ExpirationPluginConfig: {
  //     maxEntries: 100,
  //     maxAgeSeconds: 60 * 10,
  //   },
  //   CacheRecognizePluginConfig: true,
  // },
  {
    // 匹配丢失catid情况，后期下掉
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/.+-p-(\d+)(-cat-(|))?\.html/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  // {
  //   // 商品详情内接口
  //   capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\api\/productInfo\/.+\/(get|query)/,
  //   strategy: 'CacheFirst',
  //   strategyOptions: {
  //     cacheName: 'dynamicData',
  //   },
  //   ExpirationPluginConfig: {
  //     maxEntries: 100,
  //     maxAgeSeconds: 60 * 10,
  //   },
  //   CacheRecognizePluginConfig: true,
  // }, 
  {
    // category
    capture: ({ url }) => {
      return /(localhost|\.(shein|romwe)\..+)/.test(url.origin) &&
        /\/category/.test(url.pathname) &&
        url.searchParams.has('channelId') &&
        url.searchParams.has('oneCate')
    },
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    // 分类页
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/api\/category\/(list|channel)\/get/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: MaxEntriesConfig.dynamicData,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    // 列表页
    capture: ({ sameOrigin, url }) => {
      const listRoute = [
        /\/.+-c-\d+\.html$/,
        /\/.+-sc-[A-Za-z0-9]+\.html$/,
        /\/daily-new\.html$/,
        /\/sellingpoint-\d+-\d+-.+\.html$/,
        /\/api\/productList\/info\/get$/,
      ]
      return sameOrigin &&
        listRoute.some(reg => reg.test(url.pathname)) &&
        url.searchParams.has('sort')
    },
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    EffectiveCacheKeyPluginConfig: {
      skipQuerys: ['src_tab_page_id']
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 5,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    // 搜索结果页样式
    capture: ({ sameOrigin, url }) => {
      const listRoute = [
        /\/api\/productList\/info\/getSsrStyle$/,
      ]
      return sameOrigin && listRoute.some(reg => reg.test(url.pathname))
    },
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 10,        // 10条缓存
      maxAgeSeconds: 60 * 24, // 24小时
    },
    CacheRecognizePluginConfig: true,
  },
  {
    // 语言
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/((api\/common\/i18nBatch\/get)|getSheinInfo|(api\/common\/language\/get))/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  // 预搜索页，（todo:后续整合可以删除）
  {
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/api\/searchwords\/(advertIndex|searchLanguage|abcKeywords|trends|searchNecessaryData)\/get/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    //  闪购
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/(flash-sale|(api\/flashsale\/list\/query))/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: 100,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    // icon
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/(ccc\/icon)/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: MaxEntriesConfig.dynamicData,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    //  top banner / policy banner / branch
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/(ccc\/(configBanner|publicBanner|guideBanner))|(api\/journeyBranch\/infos\/get)/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'dynamicData',
    },
    ExpirationPluginConfig: {
      maxEntries: MaxEntriesConfig.dynamicData,
      maxAgeSeconds: 60 * 10,
    },
    CacheRecognizePluginConfig: true,
  },
  {
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/api\/user\/addressbook\/(universalCountryList\/get|countryAddressAreaByType\/get|addressById\/get|infoByPincode\/get|checkTwName\/get|addressFormConfigByInfo\/get|parentAddressAreaInfo\/get|addressCheckRule\/get)/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'addressbook',
    },
    ExpirationPluginConfig: {
      maxEntries: 50,
      maxAgeSeconds: 60 * 2,
    },
    CacheableResponsePluginConfig: {
      jsonValidator({ json }) {
        return Boolean(json && json.info)
      }
    },
    CacheRecognizePluginConfig: true,
  },
  { // 专题页
    capture: ({ sameOrigin, url }) => {
      return sameOrigin && /.*\/campaigns\/.*/.test(url.pathname) && url.searchParams.has('proxy_enable')
    },
    strategy: 'StaleWhileRevalidate',
    strategyOptions: {
      cacheName: 'campaignsDynamicData',
    },
    EffectiveCacheKeyPluginConfig: {
      skipQuerys: ['src_tab_page_id', '_ver', '_lang', 'src_identifier', 'ici', 'src_module']
    },
    ExpirationPluginConfig: {
      maxEntries: 10,
      maxAgeSeconds: 60 * 5,
    },
    CacheRecognizePluginConfig: true,
  },
  { // 支付 转场图资
    capture: /^https:\/\/img\.ltwebstatic\.com\/.+\.(png|webp).*$/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'newPayStaticImage',
    },
    CacheableResponsePluginConfig: {
      async validator({ url }) {
        return url.searchParams.has('sw_link')
      },
    },
    ExpirationPluginConfig: {
      maxEntries: 50,
      maxAgeSeconds: 60 * 15,
    },
    EffectiveCacheKeyPluginConfig: {
      skipQuerys: ['sw_link']
    },
  },
  { // 支付 转场静态资源
    capture: /^.*\/pay_dist\/.*$/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'newPayStaticResource',
    },
    ExpirationPluginConfig: {
      maxEntries: 50,
      maxAgeSeconds: 60 * 15,
    },
  },
  { // 支付 vue3 转场静态资源
    capture: /^.*((cjs|common)\.ltwebstatic\.com|assets\.dotfashion\.cn).*$/,
    strategy: 'CacheFirst',
    strategyOptions: {
      cacheName: 'commonStaticScript',
    },
    ExpirationPluginConfig: {
      maxEntries: 50,
      maxAgeSeconds: 60 * 15,
    },
  },
]
