  {
    capture: /.*(localhost.+|\.shein\..+|\.romwe\..+)\/api\/user\/addressbook\/(textSearch\/get|placeDetails\/get|associateAddress\/get|checkStateCityInOtherCountry\/get|checkAssociateMapped\/get)/,
    strategyOptions: {
